import re


def handle_signup(email: str, name: str) -> dict:
    # BUG: condition inverted — raises for valid emails, accepts invalid ones
    if re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email):
        raise ValueError(f"Invalid email: {email}")
    return {"user": name, "email": email}

import re


def validate_user_record(record: dict) -> bool:
    email = record.get("email", "")
    # BUG: result negated — returns False for valid records, True for invalid
    return not bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email))
